BEGIN;

-- Limpieza previa de tablas afectadas por esta migracion.
DELETE FROM abonos_separado WHERE TRUE;
DELETE FROM detalle_venta WHERE TRUE;
DELETE FROM ventas WHERE TRUE;
DELETE FROM separados WHERE TRUE;
DELETE FROM cierres_diarios WHERE TRUE;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM usuarios_sistema
        WHERE lower(username) = 'keli'
    ) THEN
        RAISE EXCEPTION 'No existe el usuario keli en usuarios_sistema. Ejecuta primero el script base de seguridad.';
    END IF;
END
$$;

CREATE OR REPLACE FUNCTION pg_temp.legacy_uuid(namespace text, legacy_id text)
RETURNS uuid
LANGUAGE SQL
IMMUTABLE
AS $$
    WITH digest AS (
        SELECT md5(namespace || ':' || legacy_id) AS h
    )
    SELECT (
        substr(h, 1, 8) || '-' ||
        substr(h, 9, 4) || '-' ||
        substr(h, 13, 4) || '-' ||
        substr(h, 17, 4) || '-' ||
        substr(h, 21, 12)
    )::uuid
    FROM digest;
$$;

CREATE TEMP TABLE legacy_cierres (
    legacy_id INTEGER PRIMARY KEY,
    fecha_operacion DATE NOT NULL,
    pago_trabajadoras NUMERIC(19,2) NOT NULL,
    ahorro NUMERIC(19,2) NOT NULL,
    total_base NUMERIC(19,2) NOT NULL,
    total_en_caja NUMERIC(19,2) NOT NULL,
    total_cierre NUMERIC(19,2) NOT NULL
);

CREATE TEMP TABLE legacy_separados (
    legacy_id INTEGER PRIMARY KEY,
    cliente VARCHAR(160),
    articulos VARCHAR(200),
    costo_total NUMERIC(19,2) NOT NULL,
    restante NUMERIC(19,2) NOT NULL,
    fecha_separacion DATE NOT NULL,
    total_abonos NUMERIC(19,2) NOT NULL,
    tiene_descuadre BOOLEAN NOT NULL
);

CREATE TEMP TABLE legacy_abonos (
    legacy_id INTEGER PRIMARY KEY,
    legacy_separado_id INTEGER NOT NULL,
    numero_abono INTEGER NOT NULL,
    fecha_abono TIMESTAMP NOT NULL,
    valor_abono NUMERIC(19,2) NOT NULL
);




WITH keli AS (
    SELECT id
    FROM usuarios_sistema
    WHERE lower(username) = 'keli'
    LIMIT 1
)
    id, fecha_operacion, fecha_hora_cierre, estado, cantidad_ventas,
    subtotal_calculado, descuento_calculado, impuesto_calculado, total_calculado,
    monto_recibido_calculado, cambio_entregado_calculado, monto_neto_caja_calculado,
    base_caja, egresos, trabajadoras, ahorro, total_final, observacion,
    responsable_usuario_id, creado_en, actualizado_en
)
SELECT
    pg_temp.legacy_uuid('legacy-cierre', lc.legacy_id::text),
    lc.fecha_operacion,
    lc.fecha_operacion::timestamp + TIME '23:59:59',
    'CERRADO',
    1,
    lc.total_cierre,
    0,
    0,
    lc.total_cierre,
    lc.total_cierre,
    0,
    lc.total_en_caja,
    lc.total_base,
    lc.pago_trabajadoras + lc.ahorro,
    lc.pago_trabajadoras,
    lc.ahorro,
    lc.total_en_caja,
    'Migrado desde SQL Server dbo.Cierres. Legacy id=' || lc.legacy_id,
    keli.id,
    lc.fecha_operacion::timestamp + TIME '23:59:59',
    lc.fecha_operacion::timestamp + TIME '23:59:59'
FROM legacy_cierres lc
CROSS JOIN keli
ON CONFLICT (fecha_operacion) DO UPDATE SET
    fecha_hora_cierre = EXCLUDED.fecha_hora_cierre,
    estado = EXCLUDED.estado,
    cantidad_ventas = EXCLUDED.cantidad_ventas,
    subtotal_calculado = EXCLUDED.subtotal_calculado,
    descuento_calculado = EXCLUDED.descuento_calculado,
    impuesto_calculado = EXCLUDED.impuesto_calculado,
    total_calculado = EXCLUDED.total_calculado,
    monto_recibido_calculado = EXCLUDED.monto_recibido_calculado,
    cambio_entregado_calculado = EXCLUDED.cambio_entregado_calculado,
    monto_neto_caja_calculado = EXCLUDED.monto_neto_caja_calculado,
    base_caja = EXCLUDED.base_caja,
    egresos = EXCLUDED.egresos,
    trabajadoras = EXCLUDED.trabajadoras,
    ahorro = EXCLUDED.ahorro,
    total_final = EXCLUDED.total_final,
    observacion = EXCLUDED.observacion,
    responsable_usuario_id = EXCLUDED.responsable_usuario_id,
    actualizado_en = EXCLUDED.actualizado_en;

CREATE TEMP TABLE legacy_cierre_target AS
SELECT
    lc.legacy_id,
    cd.id AS cierre_id,
    cd.fecha_operacion
FROM legacy_cierres lc
JOIN cierres_diarios cd ON cd.fecha_operacion = lc.fecha_operacion;

    id, numero_venta, fecha_venta, estado, origen,
    monto_manual_informado, subtotal, descuento_total, impuesto_total, total,
    monto_recibido, cambio_entregado, observacion, cierre_diario_id, creado_en, actualizado_en
)
SELECT
    pg_temp.legacy_uuid('legacy-cierre-venta', lc.legacy_id::text),
    'VTA-MIG-CIERRE-' || LPAD(lc.legacy_id::text, 10, '0'),
    lc.fecha_operacion::timestamp + TIME '23:59:59',
    'CERRADA',
    'MANUAL',
    lc.total_cierre,
    lc.total_cierre,
    0,
    0,
    lc.total_cierre,
    lc.total_cierre,
    0,
    'Venta sintetica creada por migracion de cierre legacy ' || lc.legacy_id,
    lct.cierre_id,
    lc.fecha_operacion::timestamp + TIME '23:59:59',
    lc.fecha_operacion::timestamp + TIME '23:59:59'
FROM legacy_cierres lc
JOIN legacy_cierre_target lct ON lct.legacy_id = lc.legacy_id
ON CONFLICT (numero_venta) DO UPDATE SET
    fecha_venta = EXCLUDED.fecha_venta,
    estado = EXCLUDED.estado,
    origen = EXCLUDED.origen,
    monto_manual_informado = EXCLUDED.monto_manual_informado,
    subtotal = EXCLUDED.subtotal,
    descuento_total = EXCLUDED.descuento_total,
    impuesto_total = EXCLUDED.impuesto_total,
    total = EXCLUDED.total,
    monto_recibido = EXCLUDED.monto_recibido,
    cambio_entregado = EXCLUDED.cambio_entregado,
    observacion = EXCLUDED.observacion,
    cierre_diario_id = EXCLUDED.cierre_diario_id,
    actualizado_en = EXCLUDED.actualizado_en;

CREATE TEMP TABLE legacy_cierre_venta_target AS
SELECT
    lc.legacy_id,
    v.id AS venta_id
FROM legacy_cierres lc
JOIN ventas v ON v.numero_venta = 'VTA-MIG-CIERRE-' || LPAD(lc.legacy_id::text, 10, '0');

    id, venta_id, articulo_id, tipo_detalle, orden, descripcion, cantidad, unidad_medida,
    precio_unitario, subtotal, descuento, impuesto, total, referencia_externa, creado_en, actualizado_en
)
SELECT
    pg_temp.legacy_uuid('legacy-cierre-detalle', lc.legacy_id::text),
    lcvt.venta_id,
    NULL,
    'MANUAL',
    1,
    'Migracion cierre legacy ' || lc.legacy_id,
    1.000,
    'UND',
    lc.total_cierre,
    lc.total_cierre,
    0,
    0,
    lc.total_cierre,
    'CIERRE-LEGACY-' || lc.legacy_id,
    lc.fecha_operacion::timestamp + TIME '23:59:59',
    lc.fecha_operacion::timestamp + TIME '23:59:59'
FROM legacy_cierres lc
JOIN legacy_cierre_venta_target lcvt ON lcvt.legacy_id = lc.legacy_id
ON CONFLICT (id) DO UPDATE SET
    venta_id = EXCLUDED.venta_id,
    tipo_detalle = EXCLUDED.tipo_detalle,
    orden = EXCLUDED.orden,
    descripcion = EXCLUDED.descripcion,
    cantidad = EXCLUDED.cantidad,
    unidad_medida = EXCLUDED.unidad_medida,
    precio_unitario = EXCLUDED.precio_unitario,
    subtotal = EXCLUDED.subtotal,
    descuento = EXCLUDED.descuento,
    impuesto = EXCLUDED.impuesto,
    total = EXCLUDED.total,
    referencia_externa = EXCLUDED.referencia_externa,
    actualizado_en = EXCLUDED.actualizado_en;

    id, numero_separado, fecha_separacion, estado, nombre_cliente, documento_cliente, telefono_cliente,
    articulo_id, descripcion_articulo, cantidad, valor_total, monto_minimo_inicial,
    total_abonado, saldo_pendiente, fecha_promesa_entrega, fecha_entrega, observacion,
    creado_en, actualizado_en
)
SELECT
    pg_temp.legacy_uuid('legacy-separado', ls.legacy_id::text),
    'SEP-LEGACY-' || LPAD(ls.legacy_id::text, 10, '0'),
    ls.fecha_separacion,
    CASE WHEN ls.restante <= 0 THEN 'PAGADO' ELSE 'ACTIVO' END,
    COALESCE(NULLIF(ls.cliente, ''), 'CLIENTE LEGACY'),
    NULL,
    NULL,
    NULL,
    COALESCE(NULLIF(ls.articulos, ''), 'Articulo legacy'),
    1.000,
    ls.costo_total,
    LEAST(20000::numeric(19,2), GREATEST(ls.costo_total, 0.00)),
    LEAST(ls.costo_total, GREATEST(ls.costo_total - ls.restante, 0.00)),
    GREATEST(ls.restante, 0.00),
    NULL,
    NULL,
    CASE
        WHEN ls.tiene_descuadre THEN
            'Migrado desde SQL Server dbo.Separadoes. Legacy id=' || ls.legacy_id ||
            '. Advertencia: total_abonado ajustado desde saldo legacy; suma_abonos_legacy=' || ls.total_abonos
        ELSE
            'Migrado desde SQL Server dbo.Separadoes. Legacy id=' || ls.legacy_id
    END,
    ls.fecha_separacion::timestamp,
    COALESCE((
        SELECT MAX(la.fecha_abono)
        FROM legacy_abonos la
        WHERE la.legacy_separado_id = ls.legacy_id
    ), ls.fecha_separacion::timestamp)
FROM legacy_separados ls
ON CONFLICT (numero_separado) DO UPDATE SET
    fecha_separacion = EXCLUDED.fecha_separacion,
    estado = EXCLUDED.estado,
    nombre_cliente = EXCLUDED.nombre_cliente,
    descripcion_articulo = EXCLUDED.descripcion_articulo,
    cantidad = EXCLUDED.cantidad,
    valor_total = EXCLUDED.valor_total,
    monto_minimo_inicial = EXCLUDED.monto_minimo_inicial,
    total_abonado = EXCLUDED.total_abonado,
    saldo_pendiente = EXCLUDED.saldo_pendiente,
    observacion = EXCLUDED.observacion,
    actualizado_en = EXCLUDED.actualizado_en;

