    observacion = EXCLUDED.observacion,
    cierre_diario_id = EXCLUDED.cierre_diario_id,
    actualizado_en = EXCLUDED.actualizado_en;

CREATE TEMP TABLE legacy_abono_venta_target AS
SELECT
    la.legacy_id,
    la.legacy_separado_id,
    v.id AS venta_id
FROM legacy_abonos la
JOIN ventas v ON v.numero_venta = 'VTA-MIG-ABONO-' || LPAD(la.legacy_id::text, 10, '0');

    id, venta_id, articulo_id, tipo_detalle, orden, descripcion, cantidad, unidad_medida,
    precio_unitario, subtotal, descuento, impuesto, total, referencia_externa, creado_en, actualizado_en
)
SELECT
    pg_temp.legacy_uuid('legacy-abono-detalle', la.legacy_id::text),
    lavt.venta_id,
    NULL,
    'MANUAL',
    1,
    'Abono separado ' || ('SEP-LEGACY-' || LPAD(la.legacy_separado_id::text, 10, '0')) || ' - ' || COALESCE(NULLIF(ls.articulos, ''), 'Articulo legacy'),
    1.000,
    'UND',
    la.valor_abono,
    la.valor_abono,
    0,
    0,
    la.valor_abono,
    'ABONO-LEGACY-' || la.legacy_id,
    la.fecha_abono,
    la.fecha_abono
FROM legacy_abonos la
JOIN legacy_separados ls ON ls.legacy_id = la.legacy_separado_id
JOIN legacy_abono_venta_target lavt ON lavt.legacy_id = la.legacy_id
ON CONFLICT (id) DO UPDATE SET
    venta_id = EXCLUDED.venta_id,
    tipo_detalle = EXCLUDED.tipo_detalle,
    orden = EXCLUDED.orden,
    descripcion = EXCLUDED.descripcion,
    cantidad = EXCLUDED.cantidad,
    unidad_medida = EXCLUDED.unidad_medida,
    precio_unitario = EXCLUDED.precio_unitario,
    subtotal = EXCLUDED.subtotal,
    descuento = EXCLUDED.descuento,
    impuesto = EXCLUDED.impuesto,
    total = EXCLUDED.total,
    referencia_externa = EXCLUDED.referencia_externa,
    actualizado_en = EXCLUDED.actualizado_en;

    id, separado_id, venta_id, numero_abono, fecha_abono, monto_abono, abono_inicial, observacion, creado_en, actualizado_en
)
SELECT
    pg_temp.legacy_uuid('legacy-abono', la.legacy_id::text),
    lst.separado_id,
    lavt.venta_id,
    la.numero_abono,
    la.fecha_abono,
    la.valor_abono,
    (la.numero_abono = 1),
    'Migrado desde SQL Server dbo.Abonoes. Legacy id=' || la.legacy_id,
    la.fecha_abono,
    la.fecha_abono
FROM legacy_abonos la
JOIN legacy_separado_target lst ON lst.legacy_id = la.legacy_separado_id
JOIN legacy_abono_venta_target lavt ON lavt.legacy_id = la.legacy_id
ON CONFLICT (venta_id) DO UPDATE SET
    separado_id = EXCLUDED.separado_id,
    numero_abono = EXCLUDED.numero_abono,
    fecha_abono = EXCLUDED.fecha_abono,
    monto_abono = EXCLUDED.monto_abono,
    abono_inicial = EXCLUDED.abono_inicial,
    observacion = EXCLUDED.observacion,
    actualizado_en = EXCLUDED.actualizado_en;

COMMIT;
